Q: Create a list of events with an event handler to add or remove the handler to the event list A: <p>I understand. There is a mistake in the class you provided. <strong>Every class can access and invoke all events of self-class, but not other classes.</strong> If you want to get events, you need to save the event name, not the event.</p>
<p>So your class should look like this:</p>
<pre class="lang-cs prettyprint-override"><code>using System;
using System.Reflection;

public class EventWHandler
{
    public EventWHandler(string eventName, EventHandler method)
    {
        EventName = eventName;
        Method = method;
    }

    public string EventName { get; private set; }
    public EventHandler Method { get; private set; }

    public void Listen(object target)
    {
        var eventInfo = target.GetType().GetEvent(EventName, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static);
        if (eventInfo == null)
            throw new ArgumentException($&quot;Event '{EventName}' not found on class {target.GetType().Name}&quot;);
        eventInfo.AddEventHandler(target, Method);
    }

    public void UnListen(object target)
    {
        var eventInfo = target.GetType().GetEvent(EventName, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static);
        if (eventInfo == null)
            throw new ArgumentException($&quot;Event '{EventName}' not found on class {target.GetType().Name}&quot;);
        eventInfo.RemoveEventHandler(target, Method);
    }
}
</code></pre>
<p>Now using the idea of this class, you can do this:</p>
<pre><code>list.Add(new EventWHandler(&quot;Resize&quot;, FormMain_Resize));
</code></pre>
<p>When you want to listen:</p>
<pre><code>EventWHandler ewh = /* Suppose here is your event listener defined */;
ewh.Listen(form); // Suppose `form` is your windows form
</code></pre>
<p>Or you can also create a class that implements <a href="https://learn.microsoft.com/en-us/dotnet/api/system.collections.idictionary?view=netframework-4.0" rel="nofollow noreferrer"><code>IDictionary&lt;TKey, TValue&gt;</code></a>. Then you don't need another dedicated list or <code>EventWHandler</code>. Like:</p>
<pre><code>using System;
using System.Collections;
using System.Collections.Generic;

public class EventHandlersDictionary : IDictionary&lt;string, EventHandler&gt;
{
    private readonly Dictionary&lt;string, EventHandler&gt; _innerDictionary = new Dictionary&lt;string, EventHandler&gt;();

    public EventHandler this[string key] 
    { 
        get =&gt; _innerDictionary[key];
        set =&gt; _innerDictionary[key] = value;
    }

    public ICollection&lt;string&gt; Keys =&gt; _innerDictionary.Keys;

    public ICollection&lt;EventHandler&gt; Values =&gt; _innerDictionary.Values;

    public int Count =&gt; _innerDictionary.Count;

    public bool IsReadOnly =&gt; ((IDictionary&lt;string, EventHandler&gt;)_innerDictionary).IsReadOnly;

    public void Add(string key, EventHandler value)
    {
        _innerDictionary.Add(key, value);
    }

    public void Add(KeyValuePair&lt;string, EventHandler&gt; item)
    {
        ((IDictionary&lt;string, EventHandler&gt;)_innerDictionary).Add(item);
    }

    public void Clear()
    {
        _innerDictionary.Clear();
    }

    public bool Contains(KeyValuePair&lt;string, EventHandler&gt; item)
    {
        return ((IDictionary&lt;string, EventHandler&gt;)_innerDictionary).Contains(item);
    }

    public bool ContainsKey(string key)
    {
        return _innerDictionary.ContainsKey(key);
    }

    public void CopyTo(KeyValuePair&lt;string, EventHandler&gt;[] array, int arrayIndex)
    {
        ((IDictionary&lt;string, EventHandler&gt;)_innerDictionary).CopyTo(array, arrayIndex);
    }

    public IEnumerator&lt;KeyValuePair&lt;string, EventHandler&gt;&gt; GetEnumerator()
    {
        return _innerDictionary.GetEnumerator();
    }

    public bool Remove(string key)
    {
        return _innerDictionary.Remove(key);
    }

    public bool Remove(KeyValuePair&lt;string, EventHandler&gt; item)
    {
        return ((IDictionary&lt;string, EventHandler&gt;)_innerDictionary).Remove(item);
    }

    public bool TryGetValue(string key, out EventHandler value)
    {
        return _innerDictionary.TryGetValue(key, out value);
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return _innerDictionary.GetEnumerator();
    }

    public void Listen(object target)
    {
        foreach (var kvp in _innerDictionary)
        {
            var eventInfo = target.GetType().GetEvent(kvp.Key, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static);
            if (eventInfo == null)
                throw new ArgumentException($&quot;Event '{kvp.Key}' not found on class {target.GetType().Name}&quot;);
            eventInfo.AddEventHandler(target, kvp.Value);
        }
    }

    public void UnListen(object target)
    {
        foreach (var kvp in _innerDictionary)
        {
            var eventInfo = target.GetType().GetEvent(kvp.Key, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static);
            if (eventInfo == null)
                throw new ArgumentException($&quot;Event '{kvp.Key}' not found on class {target.GetType().Name}&quot;);
            eventInfo.RemoveEventHandler(target, kvp.Value);
        }
    }
}
</code></pre>
<p>Now using the idea of this class, you can also do this:</p>
<pre><code>EventHandlersDictionary ehd = new EventHandlersDictionary()
{
    { &quot;Resize&quot;, FormMain_Resize },
    { &quot;Load&quot;, FormMain_Load }
}
</code></pre>
<p>When you want to listen:</p>
<pre><code>ehd.Listen(form); // Suppose `form` is your windows form
</code></pre>
<p>If you want to combine two delegates or more, use <code>+</code> operator between two delegates, or use <a href="https://learn.microsoft.com/en-us/dotnet/api/system.delegate.combine?view=netframework-4.0#system-delegate-combine(system-delegate())" rel="nofollow noreferrer"><code>Delegate.Combine(params Delegate[])</code></a> or <a href="https://learn.microsoft.com/en-us/dotnet/api/system.delegate.combine?view=netframework-4.0#system-delegate-combine(system-delegate-system-delegate)" rel="nofollow noreferrer"><code>Delegate.Combine(Delegate, Delegate)</code></a> then cast.</p>

