<h2>SimpleMailServlet.java</h2>
<pre class="lang-java prettyprint-override"><code>package com.example;

import javax.mail.Authenticator;
import javax.mail.Message;
import javax.mail.MessagingException;
import javax.mail.PasswordAuthentication;
import javax.mail.Session;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeMessage;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Properties;

@WebServlet(&quot;/sendMail&quot;)
public class SimpleMailServlet extends HttpServlet {

  @Override
  protected void doGet(HttpServletRequest request, HttpServletResponse response)
      throws ServletException, IOException {

    response.setContentType(&quot;text/html;charset=UTF-8&quot;);
    PrintWriter out = response.getWriter();

    // 1. SMTP server settings
    Properties props = new Properties();
    // props.put(&quot;mail.smtp.host&quot;, &quot;localhost&quot;);    // war at Host Tomcat Server
    props.put(&quot;mail.smtp.host&quot;, &quot;my-james-server&quot;); // war at Docker tomcat container

    props.put(&quot;mail.smtp.port&quot;, &quot;587&quot;);
    props.put(&quot;mail.smtp.auth&quot;, &quot;true&quot;);
    props.put(&quot;mail.smtp.starttls.enable&quot;, &quot;true&quot;);

    try {
      // For Local Apache James Docker
      // Establish an SSLSocketFactory that trusts all hosts.
      com.sun.mail.util.MailSSLSocketFactory sf = new com.sun.mail.util.MailSSLSocketFactory();
      sf.setTrustAllHosts(true);
      props.put(&quot;mail.smtp.ssl.socketFactory&quot;, sf);
    } catch (java.security.GeneralSecurityException e) {
      e.printStackTrace();
    }

    // 2. Establish verification object
    Authenticator auth = new Authenticator() {
      protected PasswordAuthentication getPasswordAuthentication() {
        return new PasswordAuthentication(&quot;user01@james.local&quot;, &quot;1234&quot;);
      }
    };

    // 3. Create a session and send an email
    Session session = Session.getInstance(props, auth);

    try {
      Message message = new MimeMessage(session);
      message.setFrom(new InternetAddress(&quot;user01@james.local&quot;));
      message.setRecipients(Message.RecipientType.TO, InternetAddress.parse(&quot;user02@james.local&quot;));
      message.setSubject(&quot;Servlet - SMTP Test&quot;);
      message.setText(&quot;This is an automated email sent from a Tomcat Servlet.&quot;);

      Transport.send(message);
      out.println(&quot;&lt;h2&gt;The email has been successfully sent!&lt;/h2&gt;&quot;);

    } catch (MessagingException e) {
      out.println(&quot;&lt;h2&gt;Sending failed:&lt;/h2&gt;&quot;);
      out.println(&quot;&lt;pre&gt;&quot; + e.getMessage() + &quot;&lt;/pre&gt;&quot;);
      e.printStackTrace();
    }

  }
}
</code></pre>
